tor/sona\": \"^0.1.5\",\n    \"agentdb\": \"^3.0.0-alpha.20\",\n    \"agentic-flow\": \"^2.0.14\",\n    \"better-sqlite3\": \"12.9.0\"\n  },\n  \"overrides\": {\n    \"ruvector\": \"^0.2.27\",\n    \"better-sqlite3\": \"12.9.0\",\n    \"js-yaml\": \">=4.3.0\",\n    \"hono\": \">=4.13.2\",\n    \"@ruvector/rvf-wasm\": \"0.1.5\",\n    \"@ruvector/rvf\": \"0.3.4\",\n    \"@hono/node-server\": \">=2.1.1\",\n    \"flatted\": \">=3.4.0\",\n    \"tar\": \">=7.5.11\",\n    \"picomatch\": \">=4.0.3\",\n    \"path-to-regexp\": \">=8.2.1\",\n    \"undici\": \">=8.10.0\",\n    \"minimatch\": \">=10.0.0\",\n    \"@isaacs/brace-expansion\": \">=5.0.1\",\n    \"cacache\": \">=20.0.0\",\n    \"make-fetch-happen\": \">=15.0.0\",\n    \"express-rate-limit\": \">=8.4.1\",\n    \"express\": \">=4.22.2\",\n    \"tinypool\": \">=2.1.2\",\n    \"qs\": \">=6.15.2\",\n    \"protobufjs\": \">=8.7.2\",\n    \"uuid\": \">=14.0.0\",\n    \"@opentelemetry/core\": \">=2.8.0\",\n    \"@opentelemetry/resources\": \">=2.8.0\",\n    \"@opentelemetry/sdk-trace-base\": \">=2.8.0\",\n    \"@opentelemetry/sdk-node\": \">=0.220.0\",\n    \"@opentelemetry/auto-instrumentations-node\": \">=0.75.0\",\n    \"@opentelemetry/exporter-prometheus\": \">=0.220.0\",\n    \"@opentelemetry/exporter-trace-otlp-grpc\": \">=0.220.0\",\n    \"@opentelemetry/exporter-trace-otlp-http\": \">=0.220.0\",\n    \"@opentelemetry/exporter-trace-otlp-proto\": \">=0.220.0\",\n    \"@opentelemetry/otlp-exporter-base\": \">=0.220.0\",\n    \"@opentelemetry/otlp-grpc-exporter-base\": \">=0.220.0\",\n    \"@opentelemetry/otlp-transformer\": \">=0.220.0\",\n    \"axios\": \">=1.19.0\",\n    \"fast-uri\": \"$fast-uri\",\n    \"vite\": \">=8.0.16\",\n    \"ws\": \">=8.21.0\",\n    \"@grpc/grpc-js\": \">=1.14.4\",\n    \"form-data\": \">=4.0.6\",\n    \"http-proxy-middleware\": \">=3.0.7\",\n    \"@ruvector/ruvllm\": \">=2.6.0\"\n  },\n  \"devDependencies\": {\n    \"@openai/codex\": \"^0.98.0\",\n    \"@types/bcrypt\": \"^5.0.2\",\n    \"@types/node\": \"^20.0.0\",\n    \"esbuild\": \"^0.27.2\",\n    \"eslint\": \"^8.0.0\",\n    \"tsx\": \"^4.21.0\",\n    \"typescript\": \"^5.0.0\",\n    \"vitest\": \"^3.2.6\"\n  },\n  \"pnpm\": {\n    \"overrides\": {\n      \"better-sqlite3\": \"12.9.0\"\n    }\n  },\n  \"engines\": {\n    \"node\": \">=20.0.0\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/ruvnet/claude-flow.git\"\n  },\n  \"keywords\": [\n    \"ruvflow\",\n    \"claude\",\n    \"claude-code\",\n    \"anthropic\",\n    \"ai\",\n    \"ai-agents\",\n    \"multi-agent\",\n    \"agent-orchestration\",\n    \"swarm-intelligence\",\n    \"swarm\",\n    \"mcp\",\n    \"model-context-protocol\",\n    \"llm\",\n    \"large-language-model\",\n    \"gpt\",\n    \"chatgpt\",\n    \"automation\",\n    \"workflow\",\n    \"orchestration\",\n    \"cli\",\n    \"developer-tools\",\n    \"devtools\",\n    \"coding-assistant\",\n    \"code-generation\",\n    \"enterprise\",\n    \"vector-database\",\n    \"embeddings\",\n    \"machine-learning\",\n    \"neural-network\",\n    \"hive-mind\",\n    \"distributed-systems\",\n    \"consensus\",\n    \"self-learning\"\n  ],\n  \"author\": \"RuvNet <ruv@ruv.io> (https://ruv.io)\",\n  \"license\": \"MIT\",\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"tag\": \"latest\"\n  },\n  \"bundleDependencies\": [\n    \"@claude-flow/codex\",\n    \"@claude-flow/mcp\",\n    \"@claude-flow/plugin-agent-federation\",\n    \"@claude-flow/security\"\n  ],\n  \"directories\": {\n    \"doc\": \"docs\",\n    \"test\": \"tests\"\n  }\n}\n"
